type ProposedCall<T> = {
  name: string;
  requiresApproval: boolean;
  execute: () => Promise<T>;
};

article.sections.5.blocks.3.text:
type CallResult<T> =
  | { status: "rejected" }
  | { status: "executed"; value: T };

article.sections.5.blocks.4.text:
async function runTool<T>(
  call: ProposedCall<T>,
  requestApproval: (name: string) => Promise<"accept" | "reject">
): Promise<CallResult<T>> {
  if (call.requiresApproval) {
    const decision = await requestApproval(call.name);
    if (decision === "reject") {
      return { status: "rejected" };
    }
  }

article.sections.5.blocks.5.text:
const value = await call.execute();
  return { status: "executed", value };
}
